-- Table structure for table `exe_step_img`
--

DROP TABLE IF EXISTS `exe_step_img`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `exe_step_img` (
  `img_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主键,图片名',
  `exe_step_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '记录执行步骤的id',
  `is_manual` tinyint(1) NOT NULL DEFAULT '0' COMMENT '状态：0-工业相机；1-人工',
  `deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '状态：0-启用；1-删除',
  `created_at` datetime DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime DEFAULT NULL COMMENT '更新时间',
  `created_by` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建操作用户的id',
  `updated_by` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新操作用户的id',
  PRIMARY KEY (`img_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='步骤拍照图片关联表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `exe_step_img`
--

LOCK TABLES `exe_step_img` WRITE;
/*!40000 ALTER TABLE `exe_step_img` DISABLE KEYS */;
